// Secure version of app.js with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressSanitizer = require('express-sanitizer');
const app = express();

// Security middleware
app.use(helmet());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(expressSanitizer());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health check endpoint (public)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Basic authentication middleware for sensitive endpoints
const basicAuth = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  if (!authHeader || authHeader !== 'Bearer secure-token') {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};

// Input validation middleware for user data
const validateUserInput = (req, res, next) => {
  // This would be expanded based on actual requirements
  if (req.query.id && !/^\d+$/.test(req.query.id)) {
    return res.status(400).json({ error: 'Invalid user ID format' });
  }
  next();
};

// Protected users endpoint
app.get('/users', basicAuth, validateUserInput, (req, res) => {
  // Sanitize data before sending (though this is mock data)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

